/*
 * A249630  Sums of the composite numbers placed between two consecutive prime
 *          numbers (A054265), sorted in increasing order.
 * https://oeis.org/A249630
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n‑th smallest sum of all composite integers * lying
 *            strictly between two consecutive primes. * The sequence is
 *            generated by computing the sums for a fixed number * of gaps,
 *            sorting them, and indexing into the sorted array
 * Range:     u8 n <= 1, u16 n <= 1, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   _floor_isqrt_u64, _prime_limit_for_idx, build_primes_upto,
 *            cmp_seq_t
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>

#include "../utils/_prime_limit_for_idx.h"
#include "../utils/_floor_isqrt_u64.h"
#include "../utils/build_primes_upto.h"
#include "../utils/cmp_seq_t.h"

static seq_t *sortedSums = NULL;       /* sorted sums of composites */
static size_t sortedSumsCnt = 0;       /* number of elements stored */
static bool initDone = false;          /* whether initialisation finished */

/*  Compute the sequence once, storing enough sums for typical
 *  requests (≈10 000 entries).  The number of gaps is generous
 *  so that the first 10 000 sorted terms are covered.  The value
 *  may be increased if higher n are required; the code will
 *  continue to work. */
static void compute_sequence(void)
{
    /* Number of prime gaps to pre‑compute.  300 000 gaps are enough
     * for >10 000 sorted terms while keeping memory and speed
     * modest. */
    const size_t GAPS = 300000U;

    /* We need one more prime than gaps. */
    const idx_t needPrimes = (idx_t)GAPS + 1U;

    /* Obtain an upper bound on the required prime. */
    idx_t prime_limit = _prime_limit_for_idx(needPrimes);

    /* Allocate primes array.  build_primes_upto guarantees enough
     * capacity for the returned number of primes. */
    uint64_t *primes   = NULL;
    size_t    primesCnt = 0;

    /* In the unlikely event that the initial bound is too low,
     * repeatedly double the limit until we have enough primes. */
    while (true) {
        build_primes_upto(prime_limit, &primes, &primesCnt);
        if (primesCnt >= needPrimes)
            break;
        free(primes);
        prime_limit <<= 1;   /* double the limit */
    }

    /* The largest prime value needed (determines sieve size). */
    const idx_t maxVal = primes[primesCnt - 1];

    /* ---------- Sieve of Eratosthenes to identify primes ---------- */
    uint8_t *is_prime = (uint8_t *)calloc((size_t)maxVal + 1ULL,
                                          sizeof(uint8_t));
    if (!is_prime) {   /* memory error – leave init incomplete */
        free(primes);
        return;
    }
    for (idx_t i = 2; i <= maxVal; ++i)
        is_prime[i] = 1;   /* assume prime */

    const idx_t sqrtMax = _floor_isqrt_u64(maxVal);
    for (idx_t i = 2; i <= sqrtMax; ++i) {
        if (is_prime[i]) {
            for (idx_t j = i * i; j <= maxVal; j += i)
                is_prime[j] = 0;   /* composite */
        }
    }

    /* -------------------------------- Prefix sums of composites -------------------------------- */
    seq_t *prefix = (seq_t *)calloc((size_t)maxVal + 1ULL,
                                    sizeof(seq_t));
    if (!prefix) {
        free(primes);
        free(is_prime);
        return;
    }

    seq_t acc = 0;
    for (idx_t i = 0; i <= maxVal; ++i) {
        if (i >= 2 && !is_prime[i])          /* composite integer */
            acc += (seq_t)i;
        prefix[i] = acc;
    }

    /* --------------------------------- Gather the sums --------------------------------- */
    sortedSums = (seq_t *)calloc(GAPS, sizeof(seq_t));
    if (!sortedSums) {
        free(primes);
        free(is_prime);
        free(prefix);
        return;
    }

    for (size_t k = 0; k < GAPS; ++k) {
        const uint64_t p = primes[k];
        const uint64_t q = primes[k + 1];
        /* Sum of composites between p and q: prefix[q-1] - prefix[p] */
        sortedSums[k] = prefix[q - 1] - prefix[p];
    }
    sortedSumsCnt = GAPS;

    /* ------------------------------ Sort the sums ----------------------------- */
    qsort(sortedSums, GAPS, sizeof(seq_t), cmp_seq_t);

    /* ---------- Free temporary data --------------------------------------- */
    free(is_prime);
    free(prefix);
    free(primes);
}

/*  Public API -------------------------------------------------------------- */
seq_t a(idx_t n)
{
    /* Initialise on first use. */
    if (!initDone) {
        compute_sequence();
        initDone = true;
    }

    /* The OEIS offset is 1; return 0 for indices outside the known range. */
    if (n < 1 || n > (idx_t)sortedSumsCnt)
        return 0;

    return sortedSums[n - 1];
}
